// proxy.js — chạy TRƯỚC khi yêu cầu hoàn tất. Mô phỏng bằng đối tượng đơn giản.
function proxy(req) {
  const loggedIn = req.cookies.session === "ok";
  if (req.path.startsWith("/dashboard") && !loggedIn) {
    return { type: "redirect", to: "/login" };
  }
  return { type: "next" };
}

console.log(JSON.stringify(proxy({ path: "/dashboard/stats", cookies: {} })));
console.log(JSON.stringify(proxy({ path: "/dashboard/stats", cookies: { session: "ok" } })));
console.log(JSON.stringify(proxy({ path: "/about", cookies: {} })));

