function proxy(req) {
  if (req.path === "/old-blog") return { type: "rewrite", to: "/blog" };
  if (req.path.startsWith("/admin") && req.role !== "admin") return { type: "redirect", to: "/login" };
  return { type: "next" };
}
console.log(proxy({ path: "/old-blog" }).type);
console.log(proxy({ path: "/admin/users", role: "user" }).type);
console.log(proxy({ path: "/home" }).type);

