function matches(pattern, path) {
  if (pattern.endsWith("/:path*")) {
    const base = pattern.slice(0, -7);
    return path === base || path.startsWith(base + "/");
  }
  return pattern === path;
}
console.log([
  matches("/dashboard/:path*", "/dashboard/a/b"),
  matches("/dashboard/:path*", "/dashboard"),
  matches("/dashboard/:path*", "/other"),
  matches("/about", "/about"),
].join(","));
